const [issueRes, ideaRes, archRes] = await Promise.all([
  tools.mcp__linear__get_issue({id:"DATA-2", includeRelations:true}),
  tools.mcp__linear__get_document({id:"9e2438fb-661d-46cc-b3aa-2f7cc568bc2b"}),
  tools.mcp__linear__get_document({id:"80172824-cc61-40e1-9573-0b2ac47c5c88"})
]);
function parse(res) {
  const raw = res?.content?.find(x=>x.type==="text")?.text;
  try { return JSON.parse(raw); } catch { return {raw}; }
}
const issue = parse(issueRes);
const docs = [parse(ideaRes), parse(archRes)];
const expectedIssueUrl = "https://linear.app/21n/issue/DATA-2/add-const-safe-field-builders-and-align-datafn-schema-inference";
const expectedDocUrls = [
  "https://linear.app/21n/document/ideation-and-product-rationale-data-2-add-const-safe-field-builders-c797894a8bca",
  "https://linear.app/21n/document/architecture-and-delivery-plan-data-2-add-const-safe-field-builders-55a5d8465be9"
];
text(JSON.stringify({
  issue: {
    id:issue.id,
    title:issue.title,
    url:issue.url,
    team:issue.team,
    teamId:issue.teamId,
    project:issue.project,
    projectId:issue.projectId,
    status:issue.status,
    statusType:issue.statusType,
    priority:issue.priority,
    assignee:issue.assignee ?? null,
    dueDate:issue.dueDate ?? null,
    documents:issue.documents,
    containsBothDirectDocumentLinks: expectedDocUrls.every(url => (issue.description || "").includes(url)),
    hasPartialWriteMarker:/association incomplete|partial.write/i.test(issue.description || "")
  },
  docs:docs.map(doc=>({
    id:doc.id,
    title:doc.title,
    url:doc.url,
    issue:doc.issue,
    backlinksToIssue:(doc.content || "").includes(expectedIssueUrl),
    hasPartialWriteMarker:/association incomplete|partial.write/i.test(doc.content || ""),
    contentLength:(doc.content || "").length
  }))
}, null, 2));

