const [upstream, project, statuses, projectIssues, searchIssues] = await Promise.all([
  tools.mcp__linear__get_issue({id:"DATA-2", includeRelations:true}),
  tools.mcp__linear__get_project({query:"013b7f72-1e10-434c-8db6-b3f19e5a15f8", includeResources:true}),
  tools.mcp__linear__list_issue_statuses({team:"454a22cf-025c-423f-9bcc-2b3142b47c62"}),
  tools.mcp__linear__list_issues({
    project:"013b7f72-1e10-434c-8db6-b3f19e5a15f8",
    team:"454a22cf-025c-423f-9bcc-2b3142b47c62",
    includeArchived:false,
    limit:250,
    fields:["id","title","description","url","status","statusType","project","projectId","team","teamId","updatedAt"]
  }),
  tools.mcp__linear__list_issues({
    query:"Nucleum DataFn field builders schema inference nullable defineSchema",
    includeArchived:false,
    limit:100,
    fields:["id","title","description","url","status","statusType","project","projectId","team","teamId","updatedAt"]
  })
]);
function p(res){const raw=res?.content?.find(x=>x.type==="text")?.text;try{return JSON.parse(raw)}catch{return raw}}
const projectIssuePayload=p(projectIssues);
const likely=(projectIssuePayload?.issues||[]).filter(i=>/field builder|schema inference|defineSchema|nullable|datafn.*field/i.test(`${i.title} ${i.description||""}`));
text(JSON.stringify({
  upstream:p(upstream),
  project:p(project),
  statuses:p(statuses),
  likelyProjectDuplicates:likely,
  broadSearch:p(searchIssues)
}, null, 2));

