 65	type RelationCapabilityKey = "timestamps" | "audit";
 66	
 67	/**
 68	 * Field definitions injected into join tables for each relation capability.
 69	 * Same field names as resource capabilities; kept separate for clarity.
 70	 */
 71	export const RELATION_CAPABILITY_FIELD_DEFS: Record<RelationCapabilityKey, CapabilityFieldDef[]> = {
 72	  timestamps: [
 73	    { name: "createdAt", type: "date", required: false, nullable: true, readonly: true, default: null },
 74	    { name: "updatedAt", type: "date", required: false, nullable: true, readonly: true, default: null },
 75	  ],
 76	  audit: [
 77	    { name: "createdBy", type: "string", required: false, nullable: true, readonly: true, default: null },
 78	    { name: "updatedBy", type: "string", required: false, nullable: true, readonly: true, default: null },
 79	  ],
 80	};
 81	
 82	/**
 83	 * Returns the field names injected by the given resolved relation capabilities.
 84	 * Output is deduplicated and ordered deterministically (canonical capability order).
 85	 */
 86	export function getRelationCapabilityFieldNames(caps: string[]): string[] {
 87	  const names: string[] = [];
 88	  const seen = new Set<string>();
 89	  for (const cap of caps) {
 90	    const defs = RELATION_CAPABILITY_FIELD_DEFS[cap as RelationCapabilityKey] ?? [];
 91	    for (const def of defs) {
 92	      if (!seen.has(def.name)) {
 93	        seen.add(def.name);
 94	        names.push(def.name);
 95	      }
 96	    }
 97	  }
 98	  return names;
 99	}
100	
101	function isObject(value: unknown): value is Record<string, unknown> {
102	  return typeof value === "object" && value !== null && !Array.isArray(value);
103	}
104	
105	function toCapabilityKey(entry: CapabilityEntry): CapabilityKey {
106	  return typeof entry === "string" ? entry : "shareable";
107	}
108	
109	function dedupeCapabilities(entries: CapabilityEntry[]): CapabilityEntry[] {
110	  const seen = new Set<CapabilityKey>();
111	  const deduped: CapabilityEntry[] = [];
112	
113	  for (const entry of entries) {
114	    const key = toCapabilityKey(entry);
115	    if (seen.has(key)) continue;
116	    seen.add(key);
117	    deduped.push(entry);
118	  }
119	
120	  return deduped;
121	}
122	
123	export function resolveCapabilities(
124	  globalCaps?: SchemaCapabilities,
125	  resourceCaps?: ResourceCapabilities,
126	): CapabilityEntry[] {
127	  const base = Array.isArray(globalCaps) ? globalCaps : [];
128	
129	  if (resourceCaps === undefined) {
130	    return dedupeCapabilities(base);
131	  }
132	
133	  if (Array.isArray(resourceCaps)) {
134	    const resolved = dedupeCapabilities(base);
135	
136	    for (const entry of resourceCaps) {
137	      const key = toCapabilityKey(entry);
138	      const existingIndex = resolved.findIndex((candidate) => toCapabilityKey(candidate) === key);
139	      if (existingIndex === -1) {
140	        resolved.push(entry);
141	        continue;
142	      }
143	      if (key === "shareable") {
144	        resolved[existingIndex] = entry;
145	      }
146	    }
147	
148	    return resolved;
149	  }
150	
151	  if (isObject(resourceCaps) && Array.isArray(resourceCaps.exclude)) {
152	    const excluded = new Set(resourceCaps.exclude);
153	    return dedupeCapabilities(
154	      base.filter((entry) => (typeof entry === "string" ? !excluded.has(entry) : true)),
155	    );
156	  }
157	
158	  return dedupeCapabilities(base);
159	}
160	
161	export function getCapabilityFields(resolvedCaps: CapabilityEntry[]): DatafnFieldSchema[] {
162	  const fields: DatafnFieldSchema[] = [];
163	  const seenFields = new Set<string>();
164	
165	  for (const capability of dedupeCapabilities(resolvedCaps)) {
166	    const key = toCapabilityKey(capability);
167	    for (const fieldDef of CAPABILITY_FIELD_DEFS[key]) {
168	      if (seenFields.has(fieldDef.name)) continue;
169	      seenFields.add(fieldDef.name);
170	      fields.push({ ...fieldDef });
171	    }
172	  }
173	
174	  return fields;
175	}

