 41	    externalProviderEgress: true,
 42	    fields: {
 43	      node: ["label", "text", "notes"],
 44	      collection: ["label"],
 45	      space: ["label"],
 46	      file: ["label"],
 47	      objective: ["label"],
 48	      task: ["label"]
 49	    }
 50	  }
 51	} as const;
 52	
 53	const nucleumDatafnSearchIndexSchemaVersion = "v2";
 54	
 55	/** Resolves the app-owned SearchFn index version for persistent local indexes. */
 56	export function resolveNucleumDatafnSearchIndexVersion(): string {
 57	  return [
 58	    "nucleum-datafn-search",
 59	    nucleumDatafnSearchIndexSchemaVersion,
 60	    stableSearchConfigHash({
 61	      defaults: nucleumDatafnSearchDefaults,
 62	      pipeline: nucleumDatafnSearchPipeline,
 63	      fields: resolveNucleumDatafnSearchResourceFields()
 64	    })
 65	  ].join(":");
 66	}
 67	
 68	/** Resolves DataFn schema search indices into SearchFn resource field mappings. */
 69	export function resolveNucleumDatafnSearchResourceFields(): NucleumDatafnSearchResourceFields {
 70	  const fields: NucleumDatafnSearchResourceFields = {};
 71	  for (const resource of nucleumDatafnSchema.resources) {
 72	    const searchFields = Array.isArray(resource.indices)
 73	      ? []
 74	      : (resource.indices && "search" in resource.indices
 75	          ? resource.indices.search
 76	          : []) ?? [];
 77	    if (searchFields.length > 0) {
 78	      fields[resource.name] = [...searchFields];
 79	    }
 80	  }
 81	  return fields;
 82	}
 83	
 84	function stableSearchConfigHash(value: unknown): string {
 85	  const raw = JSON.stringify(value);
 86	  let hash = 2166136261;
 87	  for (let i = 0; i < raw.length; i += 1) {
 88	    hash ^= raw.charCodeAt(i);
 89	    hash = Math.imul(hash, 16777619);
 90	  }
 91	  return (hash >>> 0).toString(36);
 92	}
